  "sql": "WITH _base AS (\n  SELECT\n    customers__regions.name AS \"orders.customers.regions.name\",\n    COUNT(*) AS \"orders.count_all\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  LEFT JOIN regions AS customers__regions\n    ON customers.region_id = customers__regions.id\n  WHERE\n    NOT customers.id IS NULL\n  GROUP BY\n    customers__regions.name\n), _cm_orders__net_sum AS (\n  SELECT\n    customers__regions.name AS \"orders.customers.regions.name\",\n    CAST(SUM(CAST(orders.amount - customers.discount AS DOUBLE)) AS DOUBLE) AS \"orders.net_total\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  LEFT JOIN regions AS customers__regions\n    ON customers.region_id = customers__regions.id\n  WHERE\n    NOT customers.id IS NULL\n  GROUP BY\n    customers__regions.name\n)\nSELECT\n  _base.\"orders.customers.regions.name\",\n  _cm_orders__net_sum.\"orders.net_total\",\n  _base.\"orders.count_all\"\nFROM _base\nLEFT JOIN _cm_orders__net_sum\n  ON _base.\"orders.customers.regions.name\" IS NOT DISTINCT FROM _cm_orders__net_sum.\"orders.customers.regions.name\"\nORDER BY\n  _base.\"orders.customers.regions.name\" ASC\nLIMIT 101"
